import time
import urllib.request

def get_with_retries(url: str, retries: int = 3, delay: float = 1.0) -> bytes:
    last_err = None
    for attempt in range(retries):
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                return resp.read()
        except Exception as e:
            last_err = e
            if attempt + 1 < retries:
                time.sleep(delay * (attempt + 1))
    raise RuntimeError(f"GET failed after {retries} tries") from last_err
